Variante de la page avec une IIFE (fonction exécutée dès sa définition), qui crée un compteur unique dont les méthodes partagent le même environnement :

const counter = (function () {
  let privateCounter = 0;
  function changeBy(val) {
    privateCounter += val;
  }
  return {
    increment() { changeBy(1); },
    value() { return privateCounter; },
  };
})();

Avant les classes, JavaScript n'avait pas de moyen natif de déclarer des méthodes privées : les closures permettaient de les émuler, avec les bénéfices de la programmation objet que sont le data hiding et l'encapsulation.

Exemples de la page, avec call/apply puis bind :

function add(c, d) {
  return this.a + this.b + c + d;
}
const o = { a: 1, b: 3 };
add.call(o, 5, 7); // 16
add.apply(o, [10, 20]); // 34

function f() {
  return this.a;
}
const g = f.bind({ a: "azerty" });
g(); // azerty
const h = g.bind({ a: "yoo" });
h(); // azerty : bind ne marche qu'une fois

Exemple de la page : sayHello est une callback, greeting une higher-order function.

function sayHello() {
  return "Hello, ";
}
function greeting(helloMessage, name) {
  console.log(helloMessage() + name);
}
greeting(sayHello, "JavaScript!");
// Hello, JavaScript!

